// Secrets set with `wrangler secret put` are not part of wrangler.jsonc,
// so declare them here. Merges with the Env generated by `wrangler types`.
interface Env {
  SPOTIFY_CLIENT_ID: string;
  SPOTIFY_CLIENT_SECRET: string;
}

declare namespace Cloudflare {
  interface Env {
    SPOTIFY_CLIENT_ID: string;
    SPOTIFY_CLIENT_SECRET: string;
  }
}
